#include <bits/stdc++.h>
using namespace std;

long long egcd(long long a, long long b, long long &s, long long &t) {
    long long r0 = a, r1 = b;
    s = 1; long long s1 = 0;
    t = 0; long long t1 = 1;
    while (r1 != 0) {
        long long q = r0 / r1;
        long long r2 = r0 - q * r1;
        r0 = r1; r1 = r2;
        long long s2 = s1; s1 = s - q * s1; s = s2;
        long long t2 = t1; t1 = t - q * t1; t = t2;
    }
    return r0;
}

vector<long long> tf(int n, long long M) {
    vector<long long> C(n + 1, 0);
    C[n] = 1;
    for (int k = n - 1; k >= 0; --k) {
        C[k] = (C[k + 1] * (k + 1)) % M;
        if (C[k] == 0) break;
    }
    return C;
}

long long app(int n, long long M) {
    vector<vector<vector<long long>>> K;
    K.push_back({{1}});
    for (int i = 0; i < n - 1; ++i) {
        auto &Ki = K[i];
        int ni = (int)Ki.size();
        vector<vector<long long>> Ki_(ni + i + 1, vector<long long>(i + 2, 0));
        K.push_back(Ki_);
        for (int j = 0; j < ni; ++j) {
            for (int k = 0; k < (int)Ki[j].size(); ++k) {
                long long v = Ki[j][k];
                for (int h = 0; h <= i; ++h) {
                    Ki_[j + h][k] = (Ki_[j + h][k] + v) % M;
                }
                Ki_[j + i + 1][i + 1] = (Ki_[j + i + 1][i + 1] + v) % M;
            }
        }
    }
    vector<long long> C = tf(n, M);
    long long s = 0;
    for (int i = 1; i < n; ++i) {
        auto &Ki = K[i];
        int ni = (int)Ki.size();
        int mi = (int)Ki[0].size();
        vector<vector<long long>> Si(ni, vector<long long>(mi, 0));
        for (int j = 0; j < ni; ++j) {
            Si[j][mi - 1] = Ki[j][mi - 1];
            for (int k = mi - 2; k >= 0; --k) {
                Si[j][k] = (Ki[j][k] + Si[j][k + 1]) % M;
            }
        }
        for (int j = 1; j < ni; ++j) {
            for (int k = 0; k < mi; ++k) {
                Si[j][k] = (Si[j][k] + Si[j - 1][k]) % M;
            }
        }
        long long si = 0;
        for (int j = 1; j < ni; ++j) {
            for (int k = 0; k < mi - 1; ++k) {
                si += (Ki[j][k] * Si[j - 1][k + 1]) % M;
                si %= M;
            }
        }
        long long c = C[i + 1];
        si = (si * c) % M;
        s = (s + si) % M;
    }
    return s;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    cout << app(n, m) << "\n";
    return 0;
}

